mapper.select:
SELECT FINPROD_ID id, FINPROD_NAME text , CONCAT(CONCAT('01',','),IFNULL(FINPROD_MARKET_ID ,'')) object FROM FIN_PRODUCT
FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
AND FINPROD_ID = #{initValue}
AND FINPROD_TYPE2 = #{finprodType2}

SELECT distinct A.FINPROD_ID id, IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) text, b.PAY_TYPE object
FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID
INNER JOIN FIN_CASH_INFO FCI ON A.FINPROD_ID = FCI.CHL_FINPROD_ID
INNER JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID
WHERE A.IS_CHL = #{Y}
AND A.FINPROD_TYPE2 = #{F28}
AND FCI.CHL_LEVEL = 1

    AND A.FINPROD_ID = #{initValue}


    AND FP.FINPROD_MARKET_ID = #{finprodMarketId}


    AND (FP.FINPROD_ID = #{finprodId} 
         or FP.FINPROD_ID = (SELECT C.P_FINPROD_ID  FROM FIN_PRODUCT C  WHERE C.FINPROD_ID = #{finprodId} ))


    AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
    )

SELECT distinct A.FINPROD_ID id,
 IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) text,
 b.PAY_TYPE payType,
 b.COLLECT_TYPE collectType
FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID
INNER JOIN FIN_CASH_INFO FCI ON A.FINPROD_ID = FCI.CHL_FINPROD_ID
INNER JOIN FIN_PRODUCT FP ON FCI.FINPROD_ID = FP.FINPROD_ID
WHERE A.IS_CHL = #{Y}
AND A.FINPROD_TYPE2 = #{F28}
AND FCI.CHL_LEVEL = 1

    AND A.FINPROD_ID = #{initValue}


    AND FP.FINPROD_MARKET_ID = #{finprodMarketId}


    AND (FP.FINPROD_ID = #{finprodId} 
         or FP.FINPROD_ID = (SELECT C.P_FINPROD_ID  FROM FIN_PRODUCT C  WHERE C.FINPROD_ID = #{finprodId} ))


    AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
    or
    A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
    )

SELECT DISTINCT A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, A.FINPROD_ID, A.FINPROD_NAME, A.FINPROD_ABBR, DATE_FORMAT(A.VDATE, '%Y-%m-%d') VDATE, DATE_FORMAT(A.MDATE, '%Y-%m-%d') MDATE, DATE_FORMAT(A.IDATE, '%Y-%m-%d') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, B.TYPE_4 windtypeone, B.TYPE_6,
B.TYPE_9, B.TYPE_10, B.TYPE_11,
DATE_FORMAT(T1.VDATE, '%Y-%m-%d') EXERCISE_VDATE, DATE_FORMAT(T1.MDATE, '%Y-%m-%d') EXERCISE_MDATE, DATE_FORMAT(T1.EXERCISE_DATE, '%Y-%m-%d') EXERCISE_DATE, T1.EXERCISE_PRICE,
A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
INNER JOIN FIN_EXERCISE_PLAN T1 ON T1.FINPROD_ID = A.FINPROD_ID AND T1.EXERCISE_TYPE = '01' and T1.EXERCISE_DATE IS NOT NULL AND t1.EXERCISE_DATE <= STR_TO_DATE(#{sysDate}, '%Y-%m-%d') AND NOT EXISTS ( SELECT 1 FROM FIN_EXERCISE_PLAN TT1 WHERE TT1.FINPROD_ID = T1.FINPROD_ID AND t1.EXERCISE_DATE <= STR_TO_DATE(#{sysDate}, '%Y-%m-%d') AND TT1.EXERCISE_TYPE = '01' AND TT1.EXERCISE_DATE > T1.EXERCISE_DATE )
AND NOT EXISTS ( SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.FINPROD_ID = A.FINPROD_ID AND TT.VDATE = T1.VDATE AND TT.MDATE = T1.MDATE AND TT.PS='T39' AND TT.IS_CANCEL='N' AND TT.TRADE_STATUS ='01' ) AND NOT EXISTS ( SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.FINPROD_ID = A.FINPROD_ID AND TT.VDATE = T1.VDATE AND TT.MDATE = T1.MDATE AND TT.PS='T39'
AND TT.WORKFLOW_ID != #{workflowId}
)
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_MARKET_ID = #{initValue}
AND A.IS_RIGHT = 'Y'
AND A.FINPROD_TYPE2 = #{finprodType}
